import{F as e}from"./chunks/FigureContainer.VL3Ntwlh.js";import{H as l}from"./chunks/HighLightText.D0qzB827.js";import{R as r}from"./chunks/ResourceCard.DSyPPpy0.js";import{c as o,o as b,a as n,b as p,d as i,e as a,w as t}from"./chunks/vitepress-theme-teek.VWKGyrHm.js";/* empty css                                                                               *//* empty css                                                             *//* empty css                                                                            */const T=JSON.parse('{"title":"模型优化与效率","description":"系统梳理大模型优化四大方向：PEFT 参数高效微调（LoRA/Adapter）、模型量化（GPTQ/AWQ/GGUF）、知识蒸馏与推理加速（KV Cache/Flash Attention/Speculative Decoding），涵盖原理、适用场景与选型建议。","frontmatter":{"title":"模型优化与效率","tldr":"LoRA、量化与 Flash Attention 等技术，大幅降低大模型部署门槛与成本。","description":"系统梳理大模型优化四大方向：PEFT 参数高效微调（LoRA/Adapter）、模型量化（GPTQ/AWQ/GGUF）、知识蒸馏与推理加速（KV Cache/Flash Attention/Speculative Decoding），涵盖原理、适用场景与选型建议。","tags":["概念","PEFT","模型量化","推理优化","知识蒸馏"],"categories":["大模型基础","训练与优化"],"date":"2026-06-29T09:49:52.000Z","permalink":"/llm-basic/model-optimization"},"headers":[],"relativePath":"llm-basic/model-optimization.md","filePath":"22.大模型基础/03.训练与优化/02.模型优化与效率.md"}'),c={name:"llm-basic/model-optimization.md"},v=Object.assign(c,{setup(d){return(m,s)=>(b(),o("div",null,[s[12]||(s[12]=n("h1",{id:"模型优化与效率",tabindex:"-1"},[a("模型优化与效率 "),n("a",{class:"header-anchor",href:"#模型优化与效率","aria-label":"Permalink to “模型优化与效率”"},"​")],-1)),s[13]||(s[13]=n("blockquote",null,[n("p",null,[n("strong",null,"摘要"),a(": 大模型部署面临显存与算力的双重瓶颈——7B 模型以 FP32 精度存储需 28GB 显存，170B 模型则接近 700GB。本文系统梳理了四项核心优化技术：PEFT（参数高效微调）通过低秩分解将微调参数量压缩至原模型的千分之一；模型量化以 GPTQ、AWQ、GGUF 等算法将权重精度从 FP16 降至 INT4/INT8，在精度损失可控的前提下大幅缩减显存占用；知识蒸馏利用大模型指导小模型训练，实现能力迁移；推理优化方面，KV Cache 避免重复计算，Flash Attention 通过 IO 感知优化降低显存访问，Speculative Decoding 以 draft-verify 模式加速自回归生成。这些技术的组合使用，使得百亿参数模型在消费级硬件上运行成为可能。")])],-1)),p(r,{resource:{name:"图集速览：大模型优化——让 AI 更轻、更快、更普惠",description:"如果你对大模型优化还比较陌生，建议先读这篇图集速览。用可视化图片集合和要点摘要，帮你快速理清大模型优化路径。",url:"https://mp.weixin.qq.com/s/dBAkzV6X8UHmOelIpqnWbg",type:"article",tags:["MoE","模型量化","推理优化","知识蒸馏"]}}),s[14]||(s[14]=n("h2",{id:"_1-引言",tabindex:"-1"},[a("1. 引言 "),n("a",{class:"header-anchor",href:"#_1-引言","aria-label":"Permalink to “1. 引言”"},"​")],-1)),s[15]||(s[15]=n("p",null,'一个 7B 参数的模型以 FP32 精度存储需占用 28GB 显存，而 170B 参数的模型更是高达近 700GB。若无优化技术支撑，大模型部署将沦为少数科技巨头的"特权"。',-1)),s[16]||(s[16]=n("p",null,"本文介绍的每一项技术，都致力于打破这一壁垒，让大模型真正走向普惠。",-1)),s[17]||(s[17]=n("h2",{id:"_2-peft-参数高效微调",tabindex:"-1"},[a("2. PEFT：参数高效微调 "),n("a",{class:"header-anchor",href:"#_2-peft-参数高效微调","aria-label":"Permalink to “2. PEFT：参数高效微调”"},"​")],-1)),n("p",null,[s[1]||(s[1]=a("全参数微调一个 70B 模型需要几百 GB 显存。PEFT 的目标是：",-1)),p(l,{bold:"",type:"note"},{default:t(()=>[...s[0]||(s[0]=[a("只修改极少量参数，就能达到接近全参数微调的效果",-1)])]),_:1}),s[2]||(s[2]=a("。",-1))]),s[18]||(s[18]=n("h3",{id:"_2-1-lora-low-rank-adaptation",tabindex:"-1"},[a("2.1 LoRA（Low-Rank Adaptation） "),n("a",{class:"header-anchor",href:"#_2-1-lora-low-rank-adaptation","aria-label":"Permalink to “2.1 LoRA（Low-Rank Adaptation）”"},"​")],-1)),n("p",null,[s[4]||(s[4]=a("LoRA 的核心洞察来自数学：",-1)),p(l,{bold:"",type:"note"},{default:t(()=>[...s[3]||(s[3]=[a("模型在微调时，权重变化矩阵通常是低秩的",-1)])]),_:1}),s[5]||(s[5]=a("，即可以用两个小矩阵的乘积来近似。",-1))]),s[19]||(s[19]=i(`<div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>全参数微调:  ΔW ∈ R^(d×d)    →  d² 个参数需要更新</span></span>
<span class="line"><span></span></span>
<span class="line"><span>LoRA:        ΔW = A × B</span></span>
<span class="line"><span>              A ∈ R^(d×r), B ∈ R^(r×d)   → 2×d×r 个参数</span></span>
<span class="line"><span></span></span>
<span class="line"><span>秩 r 通常取 8~64, 远小于 d (通常 4096+)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>直观对比:</span></span>
<span class="line"><span>  d=4096, r=16 时:</span></span>
<span class="line"><span>    全参数: 16,777,216 个参数需要更新</span></span>
<span class="line"><span>    LoRA:      131,072 个参数需要更新  (仅 0.78%!)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LoRA 示意图</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    原始权重 W (冻结，不更新)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    输入 x ────────┬────→ W ──────────┬────→ 输出 h</span></span>
<span class="line"><span>                   │                   │</span></span>
<span class="line"><span>                   └──→ A ──→ B ──────┘</span></span>
<span class="line"><span>                       (d×r)  (r×d)</span></span>
<span class="line"><span>                       可训练  可训练</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    h = W·x + B·A·x  = (W + ΔW)·x</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    A 用高斯分布初始化, B 用零初始化 → 训练开始时 ΔW=0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">为什么要用 LoRA？</p><ul><li><strong>显存节省</strong>：只需存储和训练两个小矩阵</li><li><strong>存储节省</strong>：一个基础模型对应多个 LoRA 适配器（不同任务各存一份小权重）</li><li><strong>无推理延迟</strong>：可以将 LoRA 权重合并回原模型（ΔW 加上 W），推理速度不变</li></ul></div><h3 id="_2-2-qlora-quantized-lora" tabindex="-1">2.2 QLoRA（Quantized LoRA） <a class="header-anchor" href="#_2-2-qlora-quantized-lora" aria-label="Permalink to “2.2 QLoRA（Quantized LoRA）”">​</a></h3><p>QLoRA 在 LoRA 的基础上更进一步——<strong>对基础模型本身也进行量化处理</strong>。</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>LoRA:   基础模型 FP16 + LoRA 适配器 FP16</span></span>
<span class="line"><span>QLoRA:  基础模型 4-bit (NF4) + LoRA 适配器 BF16</span></span>
<span class="line"><span></span></span>
<span class="line"><span>QLoRA 的关键技术:</span></span>
<span class="line"><span>  1. NF4 (4-bit NormalFloat): 专为正态分布权重设计的 4-bit 格式</span></span>
<span class="line"><span>  2. Double Quantization: 对量化常数再做一次量化, 进一步省显存</span></span>
<span class="line"><span>  3. Paged Optimizers: 用统一内存处理显存溢出</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><strong>QLoRA 的效果</strong>：用一个 48GB 显存的消费级 GPU（如 RTX 4090），就可以<strong>微调 65B 参数</strong>的模型，且质量接近全参数微调。这极大降低了 AI 开发的门槛。</p><h3 id="_2-3-其他-peft-方法对比" tabindex="-1">2.3 其他 PEFT 方法对比 <a class="header-anchor" href="#_2-3-其他-peft-方法对比" aria-label="Permalink to “2.3 其他 PEFT 方法对比”">​</a></h3><blockquote><p>当前 LoRA/QLoRA 是最主流的选择，在参数效率、训练速度和最终效果之间取得了最佳平衡。</p></blockquote><table tabindex="0"><thead><tr><th>方法</th><th>可训参数</th><th>推理开销</th><th>原理</th></tr></thead><tbody><tr><td>Adapter</td><td>~1-5% 参数</td><td>有（额外层）</td><td>在 Transformer 层间插入小网络</td></tr><tr><td>Prefix-Tuning</td><td>~0.1% 参数</td><td>占用序列长度</td><td>在每层前面加可学习的虚拟 token</td></tr><tr><td>Prompt-Tuning</td><td>~0.01% 参数</td><td>占用序列长度</td><td>仅输入层加可学习 token</td></tr><tr><td><strong>LoRA</strong></td><td><strong>~0.1-1% 参数</strong></td><td><strong>无（可合并）</strong></td><td><strong>低秩分解权重更新</strong></td></tr></tbody></table><h2 id="_3-量化-quantization" tabindex="-1">3. 量化（Quantization） <a class="header-anchor" href="#_3-量化-quantization" aria-label="Permalink to “3. 量化（Quantization）”">​</a></h2><h3 id="_3-1-什么是量化" tabindex="-1">3.1 什么是量化 <a class="header-anchor" href="#_3-1-什么是量化" aria-label="Permalink to “3.1 什么是量化”">​</a></h3><p>量化（Quantization）是一种<strong>将高精度数值映射到低精度离散值的压缩技术</strong>。在深度学习中，具体指将模型的权重和激活值从高精度浮点格式（如 FP32、FP16）转换为低精度整数格式（如 INT8、INT4），以减少模型存储占用和推理计算开销。</p><p><strong>量化的直观理解</strong></p><p>买大米不需要精确到毫克，用&quot;斤&quot;这个粗粒度单位就够了。大模型太“胖”了，普通电脑根本装不下、跑不动。量化，就是给模型“脱水”，瘦瘦身。</p><p>通过降低模型里数字的精度，模型的体积就能瞬间缩小好几倍。虽然精度会有一点点损失，但这点损失几乎不影响使用，却让普通笔记本也能跑大模型成为了现实。这就是AI能真正走进千家万户的关键原因。</p>`,16)),p(e,{type:"image",content:"https://insight-stack-1252300811.cos.ap-shanghai.myqcloud.com/img/llm-basic/training-optimization/large_to_small.png",caption:""}),s[20]||(s[20]=n("p",null,[n("strong",null,"数学形式"),a("：给定一个浮点数张量 X，量化操作可表示为：")],-1)),p(e,{type:"image",content:"https://insight-stack-1252300811.cos.ap-shanghai.myqcloud.com/img/llm-basic/training-optimization/quantization_tips.png",caption:""}),s[21]||(s[21]=n("p",null,[n("strong",null,"反量化"),a("（推理时恢复浮点值）：")],-1)),p(e,{type:"image",content:"https://insight-stack-1252300811.cos.ap-shanghai.myqcloud.com/img/llm-basic/training-optimization/de_quantization_tips.png",caption:""}),s[22]||(s[22]=i(`<p><strong>量化的两种主要范式</strong>：</p><table tabindex="0"><thead><tr><th>范式</th><th>说明</th><th>代表方法</th><th>典型用途</th></tr></thead><tbody><tr><td><strong>PTQ</strong>（Post-Training Quantization，训练后量化）</td><td>模型训练完成后再做量化，无需重新训练或只需少量校准数据</td><td>GPTQ、AWQ、GGUF</td><td>推理部署</td></tr><tr><td><strong>QAT</strong>（Quantization-Aware Training，量化感知训练）</td><td>在训练过程中模拟量化误差，让模型学会适应低精度</td><td>LLM-QAT</td><td>追求极致精度的场景</td></tr></tbody></table><h3 id="_3-2-精度级别演进" tabindex="-1">3.2 精度级别演进 <a class="header-anchor" href="#_3-2-精度级别演进" aria-label="Permalink to “3.2 精度级别演进”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌──────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                    数值精度对比                            │</span></span>
<span class="line"><span>├──────────┬──────────┬──────────┬──────────┬──────────────┤</span></span>
<span class="line"><span>│   FP32   │   FP16   │   BF16   │   INT8   │    INT4      │</span></span>
<span class="line"><span>├──────────┼──────────┼──────────┼──────────┼──────────────┤</span></span>
<span class="line"><span>│ 32 bits  │ 16 bits  │ 16 bits  │  8 bits  │   4 bits     │</span></span>
<span class="line"><span>│ 4字节     │ 2字节     │ 2字节    │  1字节    │  0.5字节     │</span></span>
<span class="line"><span>├──────────┼──────────┼──────────┼──────────┼──────────────┤</span></span>
<span class="line"><span>│ 7B模型    │ 7B 模型   │ 7B 模型  │ 7B 模型   │ 7B 模型      │</span></span>
<span class="line"><span>│ ~28 GB   │ ~14 GB   │ ~14 GB   │ ~7 GB    │ ~3.5 GB      │</span></span>
<span class="line"><span>└──────────┴──────────┴──────────┴──────────┴──────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p><strong>BF16 胜过 FP16</strong>：BF16 和 FP32 有相同的指数位数（8 位），意味着动态范围相同，但精度较低（尾数只有 7 位）。在实践中，BF16 训练比 FP16 更稳定，不需要 loss scaling 技巧。</p><h3 id="_3-3-gptq-awq-gpu-推理量化" tabindex="-1">3.3 GPTQ / AWQ（GPU 推理量化） <a class="header-anchor" href="#_3-3-gptq-awq-gpu-推理量化" aria-label="Permalink to “3.3 GPTQ / AWQ（GPU 推理量化）”">​</a></h3><p>这两种方法都针对 GPU 推理优化，目标是在保持精度的前提下量化到 INT4：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GPTQ (Post-Training Quantization):</span></span>
<span class="line"><span>  - 基于 OBQ (Optimal Brain Quantization) 的扩展</span></span>
<span class="line"><span>  - 逐列量化权重矩阵，每次量化后补偿剩余权重的误差</span></span>
<span class="line"><span>  - 处理策略: 先量化对误差不敏感的权重</span></span>
<span class="line"><span>  - 速度: 较慢(一次量化需要数小时), 但准确性高</span></span>
<span class="line"><span></span></span>
<span class="line"><span>AWQ (Activation-Aware Weight Quantization):</span></span>
<span class="line"><span>  - 关键洞察: 不是所有权重同等重要</span></span>
<span class="line"><span>  - 对&quot;显著权重&quot;(被大激活值使用的权重)保留更高精度</span></span>
<span class="line"><span>  - 通过分析激活值的分布确定哪些权重通道最重要</span></span>
<span class="line"><span>  - 速度: 比 GPTQ 快, 效果相当或更好</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>核心洞察：<strong>保护重要通道（salient channels）</strong>。AWQ 发现约 1% 的权重通道承载了绝大部分信息，只要保护好这 1%，其他 99% 量化为 4-bit 也问题不大。</p><h3 id="_3-4-gguf-cpu-推理-llama-cpp-生态" tabindex="-1">3.4 GGUF（CPU 推理 / llama.cpp 生态） <a class="header-anchor" href="#_3-4-gguf-cpu-推理-llama-cpp-生态" aria-label="Permalink to “3.4 GGUF（CPU 推理 / llama.cpp 生态）”">​</a></h3><p>GGUF 专为 CPU 推理而生：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GGUF 的特点:</span></span>
<span class="line"><span>  - 单文件分发: 模型权重 + tokenizer + 元数据全部打包</span></span>
<span class="line"><span>  - 支持多种量化级别: Q2_K, Q3_K_S/M/L, Q4_K_S/M, Q5_K_S/M, Q6_K, Q8_0...</span></span>
<span class="line"><span>  - K-quant: 混合精度，重要层用更高质量</span></span>
<span class="line"><span>  - ARM NEON / AVX2 / CUDA 多后端支持</span></span>
<span class="line"><span>  - 可以在 MacBook、树莓派甚至手机上运行 LLM</span></span>
<span class="line"><span></span></span>
<span class="line"><span>典型使用场景:</span></span>
<span class="line"><span>  用 MacBook 跑 7B 模型:</span></span>
<span class="line"><span>  Q4_K_M 量化后 ~4.4GB, 在 M2 MacBook 上可达 20+ tokens/s</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h3 id="_3-5-量化对模型质量的影响" tabindex="-1">3.5 量化对模型质量的影响 <a class="header-anchor" href="#_3-5-量化对模型质量的影响" aria-label="Permalink to “3.5 量化对模型质量的影响”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>量化级别与困惑度(Perplexity)升高:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>FP16 (baseline)  ─── 困惑度: 10.00</span></span>
<span class="line"><span>INT8             ─── 困惑度: 10.01  (几乎无影响)</span></span>
<span class="line"><span>INT4 (GPTQ/AWQ)  ─── 困惑度: 10.05  (轻微影响)</span></span>
<span class="line"><span>Q4_K_M (GGUF)    ─── 困惑度: 10.08  (可接受)</span></span>
<span class="line"><span>INT3             ─── 困惑度: 10.50  (明显退化)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>经验法则：对于 7B 以上的模型，INT4 量化几乎不影响实际使用体验；对于 3B 以下的模型，量化到 INT4 需要谨慎评估。</p><h2 id="_4-moe-混合专家-mixture-of-experts" tabindex="-1">4. MoE：混合专家（Mixture of Experts） <a class="header-anchor" href="#_4-moe-混合专家-mixture-of-experts" aria-label="Permalink to “4. MoE：混合专家（Mixture of Experts）”">​</a></h2><p><strong>MoE 是一种通过稀疏激活来扩大模型容量但不线性增加计算成本的架构范式。</strong></p><div class="tip custom-block"><p class="custom-block-title">一句话理解：</p><p><strong>把模型从一个「全部员工同时干一件事」的工厂，变成一个「每个任务只调动最相关团队」的公司。</strong></p></div>`,18)),n("p",null,[s[7]||(s[7]=n("strong",null,"核心思路",-1)),s[8]||(s[8]=a("：",-1)),p(l,{bold:"",type:"note"},{default:t(()=>[...s[6]||(s[6]=[a("将传统 Transformer 中单一的 FFN 层替换为多个并行的「专家」（Expert）子网络，每次推理时由一个 Router（门控网络）根据输入内容动态选择其中少数几个专家参与计算",-1)])]),_:1}),s[9]||(s[9]=a("。结果是——",-1)),s[10]||(s[10]=n("strong",null,"总参数量可以做到极大（数百 B 甚至上 T），但每次推理的计算量只与选中的少数专家成正比",-1)),s[11]||(s[11]=a("。",-1))]),s[23]||(s[23]=i(`<p>传统 Transformer 是<strong>密集激活</strong>（Dense）的，每次推理，所有参数都参与计算。MoE 则不同：每次只激活<strong>一部分参数</strong>（稀疏激活）。</p><h3 id="_4-1-稀疏激活原理" tabindex="-1">4.1 稀疏激活原理 <a class="header-anchor" href="#_4-1-稀疏激活原理" aria-label="Permalink to “4.1 稀疏激活原理”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>密集模型:</span></span>
<span class="line"><span>  输入 → [全部 FFN 层都计算] → 输出</span></span>
<span class="line"><span>  → 7B 参数全部参与每次推理</span></span>
<span class="line"><span></span></span>
<span class="line"><span>MoE 模型:</span></span>
<span class="line"><span>  输入 → [Router 选择 2/8 个专家] → 输出</span></span>
<span class="line"><span>  → 只有被选中的专家参与计算</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  总参数可能有 47B, 但每次推理只激活 ~13B</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><strong>工作场所类比</strong>：密集模型像一个所有员工同时处理每个任务的工厂（效率低），MoE 像一个有多个专业团队、每个任务只调用相关团队的公司（更高效）。</p><h3 id="_4-2-router-gating-机制" tabindex="-1">4.2 Router / Gating 机制 <a class="header-anchor" href="#_4-2-router-gating-机制" aria-label="Permalink to “4.2 Router / Gating 机制”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MoE 层的结构:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    输入 token x</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>         ▼</span></span>
<span class="line"><span>    ┌─────────┐</span></span>
<span class="line"><span>    │  Router  │  ← 通常是一个简单的线性层: W_gate · x</span></span>
<span class="line"><span>    │  (门控)  │</span></span>
<span class="line"><span>    └────┬────┘</span></span>
<span class="line"><span>         │ 输出: 每个专家的权重分数</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>    ┌────▼────────────────────────┐</span></span>
<span class="line"><span>    │  Softmax + Top-k 选择       │</span></span>
<span class="line"><span>    │  保留分数最高的 k 个专家     │</span></span>
<span class="line"><span>    │  (通常 k=2)                 │</span></span>
<span class="line"><span>    └────┬────────────────────────┘</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>    ┌────▼────┬──────┬──────┬──────┐</span></span>
<span class="line"><span>    │ Expert1 │Exp-2 │Exp-3 │Exp-8 │  ← 8 个 FFN 专家</span></span>
<span class="line"><span>    │   ✓     │      │  ✓   │      │  ← 只计算被选中的</span></span>
<span class="line"><span>    └────┬────┴──────┴──┬───┴──────┘</span></span>
<span class="line"><span>         │              │</span></span>
<span class="line"><span>         └──────┬───────┘</span></span>
<span class="line"><span>                │</span></span>
<span class="line"><span>         加权求和输出: y = Σ w_i · Expert_i(x)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br></div></div><p><strong>负载均衡（Load Balancing）</strong>是关键挑战。如果 Router 总是选某几个&quot;明星专家&quot;，其他专家闲置，MoE 的优势就丧失了。通常需要添加辅助损失（auxiliary loss）来鼓励均匀分配。</p><h3 id="_4-3-代表模型" tabindex="-1">4.3 代表模型 <a class="header-anchor" href="#_4-3-代表模型" aria-label="Permalink to “4.3 代表模型”">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>总参数</th><th>激活参数</th><th>专家数</th><th>Top-k</th></tr></thead><tbody><tr><td>Mixtral 8x7B</td><td>46.7B</td><td>12.9B</td><td>8</td><td>2</td></tr><tr><td>DeepSeek-V2</td><td>236B</td><td>21B</td><td>160</td><td>6</td></tr><tr><td>DeepSeek-V3</td><td>671B</td><td>37B</td><td>256</td><td>8</td></tr><tr><td>GPT-4 (传闻)</td><td>~1.8T</td><td>~280B</td><td>8/16?</td><td>2?</td></tr></tbody></table><p>MoE 让&quot;万亿参数模型&quot;有了商业可行性——DeepSeek-V3 用 MoE 将推理成本控制到传统密集模型的约 1/10。</p><h2 id="_5-model-distillation-模型蒸馏" tabindex="-1">5. Model Distillation：模型蒸馏 <a class="header-anchor" href="#_5-model-distillation-模型蒸馏" aria-label="Permalink to “5. Model Distillation：模型蒸馏”">​</a></h2><p>模型蒸馏的思想朴素而强大：让一个<strong>大模型（Teacher）</strong>教一个<strong>小模型（Student）</strong>，传递的不只是&quot;标准答案&quot;，还有&quot;思考过程&quot;。</p><h3 id="_5-1-黑盒蒸馏-vs-白盒蒸馏" tabindex="-1">5.1 黑盒蒸馏 vs 白盒蒸馏 <a class="header-anchor" href="#_5-1-黑盒蒸馏-vs-白盒蒸馏" aria-label="Permalink to “5.1 黑盒蒸馏 vs 白盒蒸馏”">​</a></h3><p><strong>黑盒蒸馏</strong>——只能访问 Teacher 的输出：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Teacher 模型 (只能通过 API 调用)</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├─→ 输入: &quot;什么是机器学习？&quot;</span></span>
<span class="line"><span>    │   输出: &quot;机器学习是人工智能的一个分支...&quot;</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├─→ 教师输出 + 正确答案 → 训练 Student 模型</span></span>
<span class="line"><span></span></span>
<span class="line"><span>优点: 不依赖 Teacher 模型的内部结构</span></span>
<span class="line"><span>缺点: 信息有限，只能学到输出层面的知识</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><strong>白盒蒸馏</strong>——可以访问 Teacher 的内部状态：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Teacher 模型 (完全可见)</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├──→ logits (输出概率分布):   传递&quot;软标签&quot;</span></span>
<span class="line"><span>    ├──→ hidden states (中间表示): 传递&quot;思考过程&quot;</span></span>
<span class="line"><span>    └──→ attention patterns:      传递&quot;注意力模式&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    Student 被训练去模仿 Teacher 在多个层面的行为</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><strong>温度参数的重要性</strong>：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Softmax 带温度 T:</span></span>
<span class="line"><span>  q_i = exp(z_i / T) / Σ exp(z_j / T)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Teacher 预测 &quot;猫&quot;(0.6), &quot;狗&quot;(0.3), &quot;汽车&quot;(0.1)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>T=1:  猫 0.6,  狗 0.3,  汽车 0.1</span></span>
<span class="line"><span>      → Student 学会&quot;选猫&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>T=5:  猫 0.35, 狗 0.33, 汽车 0.32</span></span>
<span class="line"><span>      → Student 学会&quot;即使猫最可能, 狗也很有可能, 汽车不太可能&quot;</span></span>
<span class="line"><span>      → &quot;软标签&quot;传递了更多知识!</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p><strong>蒸馏效果惊人</strong>：Gemma 2 的 2.6B 模型通过蒸馏达到了接近 7B 模型的水平。DeepSeek-R1 也用蒸馏将推理能力传递到更小的模型中。</p><h2 id="_6-flash-attention" tabindex="-1">6. Flash Attention <a class="header-anchor" href="#_6-flash-attention" aria-label="Permalink to “6. Flash Attention”">​</a></h2><p><strong>Flash Attention 是一种通过优化 GPU 显存 I/O（而非改变数学公式）来加速 Transformer Attention 计算的算法。</strong></p><p><strong>核心洞察</strong>：传统 Attention 的瓶颈不在于 GPU 算力不够，而在于计算过程中需要在慢速显存（HBM）和快速片上缓存（SRAM）之间反复搬运大矩阵——这些搬运时间远超实际计算时间。 Flash Attention 通过<strong>分块计算（Tiling）和在线 Softmax（Online Softmax）</strong>，让注意力矩阵的计算完全在 SRAM 内完成，避免将 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>n</mi><mo>×</mo><mi>n</mi></mrow><annotation encoding="application/x-tex">n \\times n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.58333em;"></span><span class="strut bottom" style="height:0.66666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit">n</span><span class="mbin">×</span><span class="mord mathit">n</span></span></span></span> 大小的中间结果写回慢速显存，从而将显存复杂度从 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>O</mi><mo>(</mo><msup><mi>n</mi><mn>2</mn></msup><mo>)</mo></mrow><annotation encoding="application/x-tex">O(n^2)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.8141079999999999em;"></span><span class="strut bottom" style="height:1.064108em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord"><span class="mord mathit">n</span><span class="vlist"><span style="top:-0.363em;margin-right:0.05em;"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span><span class="reset-textstyle scriptstyle uncramped"><span class="mord mathrm">2</span></span></span><span class="baseline-fix"><span class="fontsize-ensurer reset-size5 size5"><span style="font-size:0em;">​</span></span>​</span></span></span><span class="mclose">)</span></span></span></span> 降至 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>O</mi><mo>(</mo><mi>n</mi><mo>)</mo></mrow><annotation encoding="application/x-tex">O(n)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.02778em;">O</span><span class="mopen">(</span><span class="mord mathit">n</span><span class="mclose">)</span></span></span></span>，速度提升 2-7 倍，同时结果在数学上等价于标准 Attention。</p><div class="note custom-block github-alert"><p class="custom-block-title">一句话理解</p><p><strong>Flash Attention 没改变 Attention 做什么，而是改变了 Attention 怎么做——数据不搬家，计算就地完成。</strong></p></div><p>Transformer 的 Attention 机制时间复杂度是 O(n^2)（n 是序列长度）。Flash Attention 不是改变算法复杂度，而是通过<strong>优化 I/O</strong>（访问显存的方式）来大幅加速。</p><h3 id="_6-1-io-aware-算子优化" tabindex="-1">6.1 IO-aware 算子优化 <a class="header-anchor" href="#_6-1-io-aware-算子优化" aria-label="Permalink to “6.1 IO-aware 算子优化”">​</a></h3><p>GPU 的内存层次结构：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─────────────────────────────────────────────┐</span></span>
<span class="line"><span>│              GPU 内存层次                     │</span></span>
<span class="line"><span>│                                              │</span></span>
<span class="line"><span>│  ┌─────────────────────────────────────┐    │</span></span>
<span class="line"><span>│  │          HBM (高带宽显存)            │    │</span></span>
<span class="line"><span>│  │          ~80 GB, 慢 (~1.5 TB/s)     │    │</span></span>
<span class="line"><span>│  │  ┌─────────────────────────────┐    │    │</span></span>
<span class="line"><span>│  │  │     SRAM (片上缓存)          │    │    │</span></span>
<span class="line"><span>│  │  │     ~20 MB, 极快 (~19 TB/s)  │    │    │</span></span>
<span class="line"><span>│  └──┴─────────────────────────────┴────┘    │</span></span>
<span class="line"><span>│                                              │</span></span>
<span class="line"><span>│  瓶颈: 标准 Attention 需要反复                   │</span></span>
<span class="line"><span>│  在 HBM 和 SRAM 之间读写中间结果                 │</span></span>
<span class="line"><span>└─────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>传统 Attention 的问题：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>标准 Attention 计算:</span></span>
<span class="line"><span>1. 计算 Q·Kᵀ        → 写出到 HBM (O(n²) 大小)</span></span>
<span class="line"><span>2. 从 HBM 读回      → 做 softmax</span></span>
<span class="line"><span>3. 写出到 HBM       →</span></span>
<span class="line"><span>4. 从 HBM 读回      → 乘以 V</span></span>
<span class="line"><span>5. 写出最终结果到 HBM</span></span>
<span class="line"><span></span></span>
<span class="line"><span>问题: 注意力矩阵 (n×n) 在 HBM 和 SRAM 之间反复搬运</span></span>
<span class="line"><span>     → 大部分时间花在数据搬运而非实际计算上</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>Flash Attention 的核心思想：<strong>把注意力矩阵切分成小块，每个小块在 SRAM 中完整计算，不需要写回 HBM</strong>。</p><h3 id="_6-2-flash-attention-1-2-3-演进" tabindex="-1">6.2 Flash Attention 1 / 2 / 3 演进 <a class="header-anchor" href="#_6-2-flash-attention-1-2-3-演进" aria-label="Permalink to “6.2 Flash Attention 1 / 2 / 3 演进”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌──────────────┬──────────────────────────────────────┐</span></span>
<span class="line"><span>│ Flash Attn 1 │ 核心: Tiling + Online Softmax        │</span></span>
<span class="line"><span>│   (2022)     │ 将 Q,K,V 按块加载到 SRAM             │</span></span>
<span class="line"><span>│              │ 在 SRAM 内做逐块 softmax             │</span></span>
<span class="line"><span>│              │ 无需存储完整的注意力矩阵到 HBM        │</span></span>
<span class="line"><span>│              │ 加速: 2-4×, 显存: O(n) vs O(n²)     │</span></span>
<span class="line"><span>├──────────────┼──────────────────────────────────────┤</span></span>
<span class="line"><span>│ Flash Attn 2 │ 核心: 更好的并行 + 反向传播优化       │</span></span>
<span class="line"><span>│   (2023)     │ 序列长度维度并行                      │</span></span>
<span class="line"><span>│              │ 改进了 causal mask 的处理             │</span></span>
<span class="line"><span>│              │ 加速: 比 v1 快 ~2×                    │</span></span>
<span class="line"><span>├──────────────┼──────────────────────────────────────┤</span></span>
<span class="line"><span>│ Flash Attn 3 │ 核心: 适配 Hopper 架构 (H100)         │</span></span>
<span class="line"><span>│   (2024)     │ 利用异步执行的 warp specialization    │</span></span>
<span class="line"><span>│              │ FP8 支持                              │</span></span>
<span class="line"><span>│              │ 加速: 比 v2 快 ~1.5-2×                │</span></span>
<span class="line"><span>└──────────────┴──────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br></div></div><p><strong>为什么这很重要？</strong> 没有 Flash Attention，长上下文就是纸上谈兵。对于 128K 的上下文窗口，如果存储完整的注意力矩阵，需要 128K × 128K × 2 bytes = 32 GB 显存——这只是一个注意力头的开销。Flash Attention 通过 O(n) 的显存需求让这成为可能。</p><div class="note custom-block github-alert"><p class="custom-block-title">一句话总结</p><p></p><p>**Flash Attention 不是改变了 Attention 做什么，而是改变了 Attention 怎么做——它证明了在深度学习领域，计算不仅仅是数学问题，也是 I/O 问题。</p></div>`,35))]))}});export{T as __pageData,v as default};
